@Composable fun HomeQTV( navController: NavController, viewModel: HomeQTVViewModel = hiltViewModel() ) { val userStats by viewModel.userStats.collectAsState() val features by viewModel.features.collectAsState() val banners by viewModel.banners.collectAsState() var selectedRoute by remember { mutableStateOf("home") }
