// Barcode Card BarcodeCard( barcode = userStats.barcode, modifier = Modifier .fillMaxWidth() .padding(horizontal = 16.dp) .padding(bottom = 16.dp) ) Box( modifier = Modifier .fillMaxSize() .offset(y = (-36).dp) ) { Column( modifier = Modifier .fillMaxSize() .background(color = Color.White) .padding(bottom = 80.dp) ) { // Stats Cards Row PointAndGift(userStats) FeatureList(features) PromotionSection(banners) PromotionSection(banners) } } }
